ALTER TABLE "global_index_methodologies" ADD COLUMN IF NOT EXISTS "index_objective" TEXT, ADD COLUMN IF NOT EXISTS "index_type" TEXT NOT NULL DEFAULT 'OTHER', ADD COLUMN IF NOT EXISTS "return_variant" TEXT NOT NULL DEFAULT 'PRICE_RETURN', ADD COLUMN IF NOT EXISTS "selection_method" TEXT, ADD COLUMN IF NOT EXISTS "calculation_frequency" TEXT, ADD COLUMN IF NOT EXISTS "effective_date" DATE;
CREATE OR REPLACE VIEW "global_index_search_read" AS SELECT r.id,r.name,r.display_name,r.symbol,r.provider,r.country,r.region,r.index_type,r.return_type AS return_variant,r.verification_status,r.licensing_status FROM global_index_registry r WHERE r.active=true;
CREATE OR REPLACE VIEW "global_index_detail_read" AS SELECT r.id,r.name,r.display_name,r.symbol,r.provider,r.country,r.region,r.currency,r.index_type,r.return_type AS return_variant,s.current_level,s.previous_close,s.change,s.change_percent,s.high_52_week,s.low_52_week,s.as_of_date,s.freshness_status,r.methodology_url,COALESCE(c.details->>'constituentsState','SOURCE_PENDING') AS constituents_state,COALESCE(c.details->>'eventsState','SOURCE_PENDING') AS events_state,r.source_lineage,r.verification_status,r.licensing_status FROM global_index_registry r LEFT JOIN global_index_snapshots s ON s.index_id=r.id LEFT JOIN global_index_coverage c ON c.index_id=r.id AND c.capability='P0_DEPTH' AND c.interval='1d';
CREATE OR REPLACE VIEW "global_index_compare_read" AS SELECT r.id,r.name,r.currency,r.return_type AS return_variant,s.current_level,a.metric,a.value,a.as_of_date FROM global_index_registry r LEFT JOIN global_index_snapshots s ON s.index_id=r.id LEFT JOIN global_index_analytics a ON a.index_id=r.id;
CREATE OR REPLACE VIEW "global_index_screener_read" AS SELECT r.id,r.name,r.symbol,r.provider,r.region,r.country,r.index_type,r.return_type AS return_variant,a.metric,a.value,a.as_of_date FROM global_index_registry r LEFT JOIN global_index_analytics a ON a.index_id=r.id;
CREATE OR REPLACE VIEW "global_index_ranking_read" AS SELECT r.id,r.name,r.currency,r.return_type AS return_variant,a.metric,a.value,a.as_of_date FROM global_index_registry r JOIN global_index_analytics a ON a.index_id=r.id WHERE a.value IS NOT NULL AND (a.metric LIKE 'RETURN_%' OR a.metric LIKE 'VOLATILITY_%' OR a.metric LIKE 'MAX_DRAWDOWN_%');
